public class Solution {
    public static int recursiveSum(int[] arr) {
        return recursiveSum(arr, arr.length - 1);
    }

    private static int recursiveSum(int[] arr, int index) {
        if (index < 0) {
            return 0;
        }
        return arr[index] + recursiveSum(arr, index - 1);
    }
}

import java.util.Arrays;

public class Solution {
    public static String insertionSortPass(int[] arr, int k) {
        if (k <= 0) return Arrays.toString(arr);
        int current = arr[k];
        int j = k - 1;
        while (j >= 0 && arr[j] > current) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = current;
        return Arrays.toString(arr);
    }
}

